def equation(eps, T, params):
    S = params[0]+params[1]*T+params[2]*T**2
    k = params[3]*np.exp(params[4]*T)
    m = params[5]
    return -(S*(1-np.exp(-k*eps**m)) + (params[6]+params[7]*T)*eps + params[8]*np.log(1+params[9]*eps**2))
